[metadata] {"type": "create", "filePath": "/workspace/repo/packages/helpers/src/markdown/get-markdown-headings.ts", "content": "/** A parsed markdown heading. */
export type MarkdownHeading = {
  /** The heading level, from 1 (top-level) to 6. */
  depth: number
  /** The plain-text content of the heading with all inline formatting stripped. */
  value: string
}

/**
 * Strips inline markdown formatting from a heading value so the navigation shows clean text.
 *
 * Handles images, links, bold, italic, strikethrough, inline code and raw HTML tags. Images and
 * links are unwrapped to their alt/link text; everything else has its markers removed.
 */
const stripInlineFormatting = (input: string): string => {
  let value = input

  // Images (![alt](url)) keep the alt text. Run before links so the leading "!" is consumed.
  value = value.replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
  // Links ([text](url)) keep the link text.
  value = value.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  // Bold (**text** or __text__).
  value = value.replace(/\*\*([^*]+)\*\*/g, '$1')
  value = value.replace(/__([^_]+)__/g, '$1')
  // Strikethrough (~~text~~).
  value = value.replace(/~~([^~]+)~~/g, '$1')
  // Italic (*text* or _text_).
  value = value.replace(/\*([^*]+)\*/g, '$1')
  value = value.replace(/_([^_]+)_/g, '$1')
  // Inline code (`code`) keeps the code text.
  value = value.replace(/`([^`]+)`/g, '$1')
  // Any remaining HTML tags.
  value = value.replace(/<[^>]+>/g, '')

  return value.trim()
}

/** Matches an ATX heading: 1-6 leading hashes followed by whitespace and the heading content. */
const ATX_HEADING = /^(#{1,6})[ \t]+(.*)$/
/** Matches the trailing closing hashes of an ATX heading (e.g. "## Title ##"). */
const CLOSING_HASHES = /[ \t]+#+[ \t]*$/
/** Matches a fence opener/closer: up to three spaces of indent followed by three or more backticks or tildes. */
const FENCE = /^ {0,3}([`~])\1{2,}/
/** Matches a line that is only "=" characters, used as a setext level-1 underline. */
const SETEXT_EQUALS = /^=+[ \t]*$/
/** Matches a line that is only "-" characters, used as a setext level-2 underline. */
const SETEXT_DASHES = /^-+[ \t]*$/
/** Matches an indented code block line (four spaces or a tab). */
const INDENTED_CODE = /^(?: {4}|\t)/

/**
 * Parses a markdown string and returns its headings in document order.
 *
 * Recognizes both ATX headings (`# Heading`) and setext headings (a line of text underlined with
 * "=" or "-"). Content inside fenced or indented code blocks is ignored, and all inline formatting
 * is stripped from the returned values so they are ready to render in a navigation sidebar.
 *
 * @param markdown - The markdown string to parse
 * @returns An array of headings, each with a `depth` (1-6) and a plain-text `value`
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n\nIntro\n\nInstall\n-------')
 * // Returns:
 * // [
 * //   { depth: 1, value: 'Getting Started' },
 * //   { depth: 2, value: 'Install' },
 * // ]
 */
export const getMarkdownHeadings = (markdown: string): MarkdownHeading[] => {
  if (!markdown) {
    return []
  }

  // Normalize Windows (CRLF) and old Mac (CR) line endings before splitting.
  const lines = markdown.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')

  const headings: MarkdownHeading[] = []

  let inFence = false
  let fenceChar = ''
  let fenceLength = 0

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] ?? ''

    // Inside a fenced code block: skip lines until we find the matching closing fence.
    if (inFence) {
      const trimmed = line.replace(/^ {0,3}/, '')
      const closing = trimmed.match(/^([`~])\1*[ \t]*$/)

      if (closing && closing[1] === fenceChar && trimmed.trimEnd().length >= fenceLength) {
        inFence = false
      }

      continue
    }

    // Opening fence: remember the marker so we only close on a matching run of characters.
    if (FENCE.test(line)) {
      const run = line.replace(/^ {0,3}/, '').match(/^([`~])\1*/)

      inFence = true
      fenceChar = run?.[1] ?? '`'
      fenceLength = run?.[0].length ?? 3

      continue
    }

    // Indented code blocks are never headings.
    if (INDENTED_CODE.test(line)) {
      continue
    }

    // ATX heading (# through ######).
    const atxMatch = line.match(ATX_HEADING)

    if (atxMatch) {
      const depth = atxMatch[1]?.length ?? 1
      const content = (atxMatch[2] ?? '').replace(CLOSING_HASHES, '')

      headings.push({ depth, value: stripInlineFormatting(content.trim()) })

      continue
    }

    // Setext heading: an underline of "=" or "-" turns the previous text line into a heading.
    if (index > 0 && (SETEXT_EQUALS.test(line) || SETEXT_DASHES.test(line))) {
      const previous = lines[index - 1] ?? ''

      // The underlined line must be a plain paragraph line, not blank, indented code, an ATX
      // heading or a code fence.
      const isParagraph =
        previous.trim() !== '' &&
        !INDENTED_CODE.test(previous) &&
        !ATX_HEADING.test(previous) &&
        !FENCE.test(previous)

      if (isParagraph) {
        headings.push({
          depth: SETEXT_EQUALS.test(line) ? 1 : 2,
          value: stripInlineFormatting(previous.trim()),
        })
      }
    }
  }

  return headings
}
